mapper.select:
SELECT * from ( SELECT ba.`name` auxiliaryName,ba.code auxiliaryCode,ba.auxiliary_id FROM book_voucher_record bvr LEFT JOIN book_voucher bv ON bvr.voucher_id = bv.voucher_id LEFT JOIN book_subject bs on bvr.subject_id = bs.subject_id LEFT JOIN book_auxiliary ba ON ba.auxiliary_id = bvr.supplier_id
LEFT JOIN book_auxiliary ba ON ba.auxiliary_id = bvr.customer_id
LEFT JOIN book_auxiliary ba ON ba.auxiliary_id = bvr.project_id
LEFT JOIN book_auxiliary ba ON ba.auxiliary_id = bvr.department_id
LEFT JOIN book_auxiliary ba ON ba.auxiliary_id = bvr.person_id
LEFT JOIN book_auxiliary ba ON ba.auxiliary_id = bvr.stock_id
where bvr.del_flag = '0' and bv.book_id = #{bookId} and bs.code LIKE CONCAT('',(SELECT code from book_subject where subject_id = #{subjectId} and book_id = #{bookId}) ,'%') and bv.year_period >= #{startPeriod} and bv.year_period <= #{endPeriod}
and ba.auxiliary_type_id = #{auxiliaryTypeId}
and ba.auxiliary_id = #{auxiliaryId}
UNION ALL SELECT ba.`name` auxiliaryName,ba.code auxiliaryCode,ba.auxiliary_id FROM book_auxiliary_period bap LEFT JOIN book_auxiliary ba ON bap.auxiliary_id = ba.auxiliary_id LEFT JOIN book_subject bs on bs.subject_id = bap.subject_id where bs.code LIKE CONCAT('',(SELECT code from book_subject where subject_id = #{subjectId} and book_id = #{bookId}) ,'%') and YEAR(bap.year_period) >= YEAR(#{startPeriod}) and YEAR(bap.year_period) <= YEAR(#{endPeriod}) and bap.year_period <= #{endPeriod} and bap.period_end_balance != 0
and ba.auxiliary_type_id = #{auxiliaryTypeId}
and ba.auxiliary_id = #{auxiliaryId}
) a group by auxiliary_id

SELECT IF(bs.balance_direction='CREDIT',SUM(bap.period_end_balance),0) startCredit, IF(bs.balance_direction='DEBIT',SUM(bap.period_end_balance),0) startDebit from book_auxiliary_period bap LEFT JOIN book_auxiliary ba ON bap.auxiliary_id = ba.auxiliary_id LEFT JOIN book_subject bs on bs.subject_id = bap.subject_id where bap.subject_id = #{subjectId} and bap.year_period = #{currentPeriod} and bap.del_flag = '0'
and ba.auxiliary_type_id = #{auxiliaryTypeId}
and ba.auxiliary_id = #{auxiliaryId}
